#!/usr/bin/perl -w
###############################################################################
# This script compiles the translated text files localizedstring-*.txt into
# header files that can be used by the FMSLogo source code.
# It also generates the internationalizedstrings.h and localizedstrings.cpp
# files.
###############################################################################

use strict;
use IO::File;

$main::GeneratedFileWarning = "// This file was generated by mklocale.pl.  Do not modify it.";

sub CopyTextFileToHeaderFile($) {
  my $CountryCode = shift or die "too few arguments";

  my $textFile = new IO::File "localizedstrings-$CountryCode.txt" or
    die "Unable to read localizedstrings-$CountryCode.txt: $!";
  $textFile->binmode(":utf8");

  # Remove the BOM so that we don't write it into the header file.
  my $bom;
  $textFile->read($bom, 1);

  my $newHeaderFile = new IO::File "> localizedstrings-$CountryCode.h" or
    die "Unable to write to localizedstrings-$CountryCode.h: $!";

  # Add a notice that the header file should not be modified directly.
  print $newHeaderFile "$main::GeneratedFileWarning\n";

  while (<$textFile>) {
    # Convert all strings "" to wide string literals L"",
    # being careful ignore strings within "//" comments
    # and being careful to honor escaped double-quotes \".
    if ($_ !~ m!^//!) {
      s/("[^"]*?(\\"[^"]*?)*")/L$1/g;
    }

    # Replace all non-ASCII characters with the corresponding
    # C++ string literal escape sequence.  For example, a
    # lower-case 'e' with an acute access becomes "\x00E9".
    #
    # It's safe to replace all such characters because they should
    # only occur within string literals.
    s/([^\x00-\x7F])/sprintf('\\x%04X', ord($1))/ge;

    # The \x is defined to be followed by one or more hexadecimal digits.
    # To prevent our replacement from mis-interpreting numbers or letters
    # which happen to follow an escaped character, we split the string
    # literal wherever such mis-interpretation would occur.
    #
    # While we could use "\u" for the escape sequence, which escapes
    # exactly four hexadecimal digits, this escape sequence is not
    # recognized by recent versions of i686-w64-mingw32-windres.
    s/(\\x[0-9A-Fa-f]{4})([0-9A-Fa-f])/$1" L"$2/g;

    # Write this line to the header file.
    print $newHeaderFile $_;
  }
  $textFile->close();
  $newHeaderFile->close();
}

sub ExtractFormatParameters($) {
  my $Translation = shift or die "too few arguments";
  my ($stringLiteral) = $Translation =~ m/"([^\\]*(\\.[^\\]*)*)"/; # extract the string literal ""
  return '' if not $stringLiteral;
  $stringLiteral =~ s/.*?(%(s|ls|d))?/$1 || ''/ge; # strip out everything exect %ls, %s, and %d
  return $stringLiteral;
}

sub UpdateLocalizationFiles($$$) {
  my $CountryCode = shift or die "too few arguments";
  my $LocaleName  = shift or die "too few arguments";
  my $Translator  = shift or die "too few arguments";

  my %translations = ();

  #
  # Build a table of everything that has already been translated
  #
  my $localizedFilename = "localizedstrings-$CountryCode.txt";
  my $existingStringTable = new IO::File $localizedFilename;
  if ($existingStringTable) {
    $existingStringTable->binmode(":utf8");
    while (<$existingStringTable>) {
      chomp;
      if (m/^#define\s+([\w\d_]+)\s*(.*)$/) {
        my $symbolicName = $1;
        my $translation  = $2;
        if ($translation !~ m!// NOT_YET_LOCALIZED!) {
            $translations{$symbolicName} = $translation;
        }
      }
    }
    $existingStringTable->close();
  }

  #
  # Write out the new localization using the English one as a basis
  #
  my $newTextFile = new IO::File "> $localizedFilename" or
    die "Unable to write to $localizedFilename: $!";
  $newTextFile->binmode(":utf8");

  my $lineNumber = 0;
  my $original = new IO::File "localizedstrings-en.txt" or
    die "Unable to read localizedstrings-en.txt: $!";
  $original->binmode(":utf8");
  while (<$original>) {
    chomp;
    my $line = $_;
    $lineNumber++;

    if ($line =~ m/^#define\s+([\w\d_]+)(\s*)(.*)$/) {
      my $token       = $1;
      my $space       = $2;
      my $translation = $3;

      if ($CountryCode eq 'ps') {
        # This is the pseudo locale, which means that the
        # translation is to add "pseudo." to the front of the
        # English translation.  Note that URLs are not translated.
        if ($translation !~ m/^"https:\/\//) {
          $translation =~ s/^"(\s*)/"$1pseudo./;
        }
        print $newTextFile "#define $token$space$translation\n";
      }
      elsif ($translations{$token}) {
        # This has already been localized.
        print $newTextFile "#define $token$space$translations{$token}\n";

        # warn if %ls, %s, or %d does not match up.
        my $englishFormatParameters    = ExtractFormatParameters($translation);
        my $translatedFormatParameters = ExtractFormatParameters($translations{$token});
        if ($englishFormatParameters ne $translatedFormatParameters) {
          print STDERR "$localizedFilename:$lineNumber: error: English text for $token has format parameters \"$englishFormatParameters\", but $CountryCode has \"$translatedFormatParameters\"\n";
        }
      }
      else {
        # This has not yet been translated.
        # Append a stylized comment indicating that this should be localized.
        print $newTextFile "$line // NOT_YET_LOCALIZED\n";
      }
    }
    elsif ($line =~ m/localized strings for English/) {
      # translate the locale English
      $line =~ s/English/$LocaleName by $Translator/;
      print $newTextFile "$line\n";
    }
    else {
      # this line is not localizable
      print $newTextFile "$line\n";
    }
  }

  $original->close();
  $newTextFile->close();

  #
  # Copy the translated file into an ASCII C++ header file.
  #
  CopyTextFileToHeaderFile($CountryCode);
}

# Writes a C declaration for a global variable to a header file
# and the corresponding C definition to the source file.
sub AddInternationalizedVariable($$$$$) {
  my $DeclarationFile    = shift or die "too few arguments";
  my $DefinitionFile     = shift or die "too few arguments";
  my $Type               = shift or die "too few arguments";
  my $Name               = shift or die "too few arguments";
  my $Value              = shift or die "too few arguments";

  print $DeclarationFile "extern $Type $Name;\n";
  print $DefinitionFile  "$Type $Name = $Value;\n";
}

sub GenerateInternationalizedFiles() {
  my $textFile = new IO::File "localizedstrings-en.txt" or
    die "Unable to read localizedstrings-en.txt: $!";
  $textFile->binmode(":utf8");

  # Remove the BOM so that we don't write it into the header file.
  my $bom;
  $textFile->read($bom, 1);

  my $headerFile = new IO::File "> internationalizedstrings.h" or
    die "Unable to write to internationalizedstrings.h: $!";

  my $sourceFile = new IO::File "> localizedstrings.cpp" or
    die "Unable to write to localizedstrings.cpp: $!";

  # Write the banner comment for the header file.
  print $headerFile <<END_OF_HEADER;
$main::GeneratedFileWarning
/////////////////////////////////////////////////////////////////////////////
// This file contains declarations for variables which hold strings that
// have been translated for a particular locale.  By compiling with this
// header file, the resulting object file is locale-neutral, as the
// locale-specific translations are linked in to the final locale-specific
// executable from the corresponding localizedstring-*.o file.
/////////////////////////////////////////////////////////////////////////////

#ifndef __INTERNATIONALIZED_STRINGS_H_
#define __INTERNATIONALIZED_STRINGS_H_

END_OF_HEADER

  # Write the banner comment for the source code.
  print $sourceFile <<END_OF_HEADER;
$main::GeneratedFileWarning
/////////////////////////////////////////////////////////////////////////////
// This file contains definitions for variables which hold strings that
// have been translated for a particular locale.
/////////////////////////////////////////////////////////////////////////////

#include "internationalizedstrings.h"
#include "localizedstrings.h"

END_OF_HEADER

  while (<$textFile>) {
    # For every line in the translated text file of the form:
    #
    #   #define THIS_STRING "this translation"
    #
    # Write a line to the header file like:
    #
    #   extern const wchar_t * const g_THIS_STRING;
    #
    # And write a line to the source file like:
    #
    #   const wchar_t * const g_THIS_STRING = THIS_STRING;
    #
    if ($_ =~ /^#define\s+(\w+)/) {
      AddInternationalizedVariable($headerFile, $sourceFile, 'const wchar_t * const', "g_$1", $1);
    }
  }

  # Create some variables which hold translations that are concatenations of other translations.
  AddInternationalizedVariable($headerFile, $sourceFile, 'const wchar_t * const', 'g_LOCALIZED_READER_ENDER', 'L"\n" LOCALIZED_ALTERNATE_END L"\n"');
  AddInternationalizedVariable($headerFile, $sourceFile, 'const wchar_t * const', 'g_LOCALIZED_STATUS_VECTORS_COLON', 'LOCALIZED_STATUS_VECTORS ":"');
  AddInternationalizedVariable($headerFile, $sourceFile, 'const wchar_t * const', 'g_LOCALIZED_STATUS_POLYGONS_COLON', 'LOCALIZED_STATUS_POLYGONS ":"');

  # MANUAL_HAS_TRANSLATION_TABLES is defined in localizedstrings.h.
  AddInternationalizedVariable($headerFile, $sourceFile, 'const bool', 'g_MANUAL_HAS_TRANSLATION_TABLES', 'MANUAL_HAS_TRANSLATION_TABLES ? true : false');

  # LOCALE is defined in Makefile and passed into the compiler as -DLOCALE=XXXX
  AddInternationalizedVariable($headerFile, $sourceFile, 'const int', 'g_LOCALE', 'LOCALE');

  # Close the #ifndef/#define/#endif guard to prevent multiple inclusion.
  print $headerFile "\n#endif // __INTERNATIONALIZED_STRINGS_H_\n";

  $headerFile->close();
  $sourceFile->close();
}


GenerateInternationalizedFiles();
CopyTextFileToHeaderFile('en');
UpdateLocalizationFiles('zh-cn', 'Chinese',    'Pachleng');
UpdateLocalizationFiles('fr',    'French',     'Bertrand CARETTE');
UpdateLocalizationFiles('gr',    'Greek',      'Theodoros Chatzigiannakis');
UpdateLocalizationFiles('es',    'Spanish',    'Daniel Ajoy');
UpdateLocalizationFiles('it',    'Italian',    'Stefano Federici and Francesco Simone Carta');
UpdateLocalizationFiles('pt',    'Portuguese', 'Alexandre R Soares');
UpdateLocalizationFiles('de',    'German',     'Stephan Vogel');
UpdateLocalizationFiles('ru',    'Russian',    'Igor Baglaev');
UpdateLocalizationFiles('hr',    'Croatian',   'Domagoj Kuna');
UpdateLocalizationFiles('pl',    'Polish',     'Andrzej Pruszynski');
UpdateLocalizationFiles('si',    'Slovene',    'Jelko Urbancic');
UpdateLocalizationFiles('ps',    'Pseudoloc',  'David Costanzo');
